CREATE TABLE bookings.admin_exceptions(order_id uuid PRIMARY KEY REFERENCES bookings.orders(id),state text NOT NULL CHECK(state IN ('open','escalated','resolved')),assigned_to uuid,version integer NOT NULL DEFAULT 1,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX booking_exception_assignment ON bookings.admin_exceptions(assigned_to,state);
CREATE TABLE bookings.admin_exception_history(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,order_id uuid NOT NULL REFERENCES bookings.orders(id),actor_id uuid NOT NULL,action text NOT NULL,reason text NOT NULL,before_data jsonb,after_data jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION bookings.immutable_exception_history() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Booking exception history is immutable'; END $$;
CREATE TRIGGER booking_exception_history_immutable BEFORE UPDATE OR DELETE ON bookings.admin_exception_history FOR EACH ROW EXECUTE FUNCTION bookings.immutable_exception_history();
CREATE TABLE bookings.admin_exception_commands(actor_id uuid NOT NULL,key text NOT NULL,fingerprint text NOT NULL,result jsonb NOT NULL,PRIMARY KEY(actor_id,key));
ALTER TABLE identity.admin_role_permissions DROP CONSTRAINT admin_role_permissions_permission_check;
ALTER TABLE identity.admin_role_permissions ADD CONSTRAINT admin_role_permissions_permission_check CHECK(permission IN ('access.manage','customers.read','bookings.read','finance','support','support_assign','moderate','pricing','audit','flights.read','flights.manage','hotels.read','hotels.manage','hotels.review','buses.read','buses.manage','trains.read','trains.manage','packages.read','packages.manage','packages.review','cabs.read','cabs.manage','bookings.manage'));
